 interface Presenter{void showCast();}static WeakReference<Presenter> visible=new WeakReference<Presenter>(null);static CastService instance;final Handler main=new Handler();final HashMap<String,UpnpRenderer> receivers=new HashMap<>();final ExecutorService images=Executors.newSingleThreadExecutor();MediaPlayer media;boolean prepared=false,photoMode=false,failed=false,hasVideo=false,videoRendered=false,completed=false;Bitmap photo;SurfaceHolder display;Surface videoSurface;UpnpRenderer active;int generation=0,dismissedGeneration=-1,videoWidth=0,videoHeight=0;long nextScan=0,stopSerial=0,preparedAt=0;volatile long exitEpoch=0;String detail="Starting receiver",title="legacydash",lastNotice="";
 static List<InetAddress> addresses(){ArrayList<InetAddress> list=new ArrayList<>();try{Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();while(interfaces.hasMoreElements()){NetworkInterface net=interfaces.nextElement();if(!net.isUp()||net.isLoopback())continue;Enumeration<InetAddress> ips=net.getInetAddresses();while(ips.hasMoreElements()){InetAddress ip=ips.nextElement();if(ip instanceof Inet4Address&&ip.isSiteLocalAddress())list.add(ip);}}}catch(Exception ignored){}Collections.sort(list,(a,b)->a.getHostAddress().compareTo(b.getHostAddress()));return list;}
 public void onCreate(){super.onCreate();instance=this;if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("legacydash.cast","legacydash receiver",NotificationManager.IMPORTANCE_LOW));startForeground(1801,notice("Receiving DLNA casts in background"));main.post(tick);}
 Notification notice(String text){int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)flags|=PendingIntent.FLAG_IMMUTABLE;Intent show=new Intent(this,CastPlayerActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent open=PendingIntent.getActivity(this,1803,show,flags),stop=PendingIntent.getService(this,1802,new Intent(this,CastService.class).setAction("stop"),flags);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"legacydash.cast"):new Notification.Builder(this);return builder.setSmallIcon(R.drawable.ic_sky).setContentTitle("legacydash / background receiver").setContentText(text).setContentIntent(open).setOngoing(true).addAction(android.R.drawable.ic_media_pause,"Disable receiver",stop).build();}
