 void scan(){List<InetAddress> addresses=addresses();HashSet<String> live=new HashSet<>();for(InetAddress address:addresses)live.add(address.getHostAddress());for(String key:new ArrayList<String>(receivers.keySet()))if(!live.contains(key)){UpnpRenderer old=receivers.remove(key);if(old==active)active=null;old.close();}android.content.SharedPreferences preferences=getSharedPreferences("sky",0);String uuid=preferences.getString("dlna.uuid","");if(uuid.isEmpty()){uuid=UUID.randomUUID().toString();preferences.edit().putString("dlna.uuid",uuid).apply();}String name=preferences.getString("dlna.name","legacydash");if(name.trim().isEmpty())name="legacydash";for(InetAddress address:addresses){String key=address.getHostAddress();if(receivers.containsKey(key))continue;try{final UpnpRenderer[] slot=new UpnpRenderer[1];slot[0]=new UpnpRenderer(getApplicationContext(),address,name,uuid,(action,args)->{final long epoch=exitEpoch;main.post(()->{if(epoch==exitEpoch)command(slot[0],action,args);});});receivers.put(key,slot[0]);}catch(Exception error){detail="Receiver unavailable on "+key+" / "+error.getClass().getSimpleName();}}}
