 void requestPresentation(){if(active==null||!active.wantPlay||failed||active.uri.isEmpty()||dismissedGeneration==generation)return;Presenter presenter=visible.get();if(presenter!=null){presenter.showCast();return;}if(Build.VERSION.SDK_INT<29)try{startActivity(new Intent(this,CastPlayerActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));}catch(Exception ignored){} }
 void command(UpnpRenderer source,String action,Map<String,String> args){if(source==null||!receivers.containsValue(source))return;active=source;sync(source);if(action.equals("SetAVTransportURI")){load(args.get("CurrentURI"),args.get("CurrentURIMetaData"));return;}try{if(action.equals("Play")){if(prepared&&media!=null)media.start();detail=prepared||photo!=null?"Playing":"Preparing received media";requestPresentation();}else if(action.equals("Pause")){if(prepared&&media!=null)media.pause();detail="Paused";}else if(action.equals("Stop")){stopSerial++;if(prepared&&media!=null){media.pause();media.seekTo(0);}detail="Stopped";}else if(action.equals("Seek")&&prepared&&media!=null)media.seekTo((int)Math.min(Integer.MAX_VALUE,source.position));else if(action.equals("SetVolume")||action.equals("SetMute"))volume();}catch(Exception error){fail("Playback command failed / "+error.getClass().getSimpleName());}sync(source);}
 void releaseMedia(){generation++;prepared=false;hasVideo=false;videoRendered=false;videoWidth=videoHeight=0;preparedAt=0;if(media!=null){try{media.reset();media.release();}catch(Exception ignored){}media=null;}photo=null;}
 void stopForExit(){exitEpoch++;releaseMedia();dismissedGeneration=generation;failed=false;completed=false;photoMode=false;stopSerial++;for(UpnpRenderer receiver:receivers.values())synchronized(receiver){receiver.wantPlay=false;receiver.uri="";receiver.metadata="";receiver.position=0;receiver.duration=0;receiver.state="STOPPED";receiver.status="OK";}detail="Cast stopped / ready for a new cast";}
 void load(String address,String metadata){releaseMedia();failed=false;completed=false;int stamp=generation;title="Received media";String mime="";if(metadata!=null)try{Map<String,String> values=UpnpRenderer.parse(metadata);if(values.containsKey("title"))title=values.get("title");if(metadata.contains("image/"))mime="image";}catch(Exception ignored){}if(address==null){fail("Missing media URL");return;}String path=android.net.Uri.parse(address).getPath();path=path==null?"":path.toLowerCase(Locale.US);photoMode=mime.equals("image")||path.endsWith(".jpg")||path.endsWith(".jpeg")||path.endsWith(".png")||path.endsWith(".gif");detail=photoMode?"Loading image":"Preparing media";if(photoMode){images.submit(()->{try{Bitmap bitmap=downloadImage(address);main.post(()->{if(stamp!=generation||instance!=this){bitmap.recycle();return;}photo=bitmap;detail="Received image";if(active!=null){active.state=active.wantPlay?"PLAYING":"STOPPED";sync(active);}requestPresentation();});}catch(Exception error){main.post(()->{if(stamp==generation&&instance==this)fail("Image unavailable / "+error.getClass().getSimpleName());});}});return;}try{MediaPlayer player=new MediaPlayer();media=player;if(Build.VERSION.SDK_INT>=21)player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MOVIE).build());else player.setAudioStreamType(AudioManager.STREAM_MUSIC);player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);if(videoSurface!=null&&videoSurface.isValid())player.setSurface(videoSurface);else if(display!=null&&display.getSurface().isValid())player.setDisplay(display);player.setOnVideoSizeChangedListener((mp,w,h)->{if(mp!=media||stamp!=generation)return;videoWidth=w;videoHeight=h;if(w>0&&h>0)hasVideo=true;});player.setOnInfoListener((mp,what,extra)->{if(mp==media&&what==MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START){videoRendered=true;detail="Playing video";}return false;});player.setOnPreparedListener(mp->{if(mp!=media||stamp!=generation)return;prepared=true;preparedAt=SystemClock.elapsedRealtime();videoWidth=mp.getVideoWidth();videoHeight=mp.getVideoHeight();hasVideo=videoWidth>0&&videoHeight>0;try{for(MediaPlayer.TrackInfo track:mp.getTrackInfo())if(track.getTrackType()==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_VIDEO)hasVideo=true;}catch(Exception ignored){}volume();if(active!=null){active.duration=Math.max(0,mp.getDuration());if(active.wantPlay){mp.start();active.state="PLAYING";}else active.state="STOPPED";sync(active);}detail=hasVideo?"Video ready / waiting for first frame":"Audio ready";requestPresentation();});player.setOnCompletionListener(mp->{if(mp!=media)return;completed=true;detail="Playback finished";if(active!=null){active.state="STOPPED";active.wantPlay=false;sync(active);}});player.setOnErrorListener((mp,what,extra)->{if(mp==media){String reason=extra==-1004?"network or file I/O":extra==-1007?"malformed media":extra==-1010?"unsupported codec or feature":extra==-110?"timed out":what==100?"media server stopped":"player failure";android.util.Log.e("LegacyDashCast","MediaPlayer error what="+what+" extra="+extra);fail("Playback error "+what+" / "+extra+" / "+reason);}return true;});player.setDataSource(address);player.prepareAsync();}catch(Exception error){android.util.Log.e("LegacyDashCast","Open failed: "+error.getClass().getSimpleName());fail("Cannot open media / "+error.getClass().getSimpleName());}}
 Bitmap downloadImage(String address)throws Exception{HttpURLConnection connection=(HttpURLConnection)new URL(address).openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(15000);try{int status=connection.getResponseCode();if(status<200||status>=300)throw new IOException("HTTP "+status);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=connection.getInputStream()){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(bytes.size()+count>20000000)throw new IOException("Image too large");bytes.write(buffer,0,count);}}byte[] data=bytes.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth<1||options.outHeight<1)throw new IOException("Unsupported image");options.inSampleSize=1;while(options.outWidth/options.inSampleSize>1200||options.outHeight/options.inSampleSize>800)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap result=BitmapFactory.decodeByteArray(data,0,data.length,options);if(result==null)throw new IOException("Unsupported image");return result;}finally{connection.disconnect();}}
 void fail(String message){failed=true;detail=message;if(active!=null){active.state="STOPPED";active.status="ERROR_OCCURRED";active.wantPlay=false;sync(active);}}
 void volume(){if(media!=null&&active!=null)try{float amount=active.muted?0:active.volume/100f;media.setVolume(amount,amount);}catch(Exception ignored){}}
 void attachSurface(Surface surface){if(videoSurface==surface)return;try{if(media!=null)media.setSurface(surface);videoSurface=surface;}catch(Exception error){detail="Video output unavailable / "+error.getClass().getSimpleName();android.util.Log.w("LegacyDashCast","Video surface attachment failed");}}
