 final Runnable tick=new Runnable(){public void run(){if(instance!=CastService.this)return;long now=SystemClock.elapsedRealtime();if(now>=nextScan){nextScan=now+15000;scan();}if(prepared&&media!=null&&active!=null)try{active.position=Math.max(0,media.getCurrentPosition());active.duration=Math.max(0,media.getDuration());sync(active);}catch(Exception ignored){}String message=network()+" / "+detail;if(!message.equals(lastNotice)){lastNotice=message;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(1801,notice(message));}main.postDelayed(this,1000);}};
